    def start_run(body: dict):
        # Role 1/2 implementation is supplied by an injected engine adapter.
        run = {"id": str(uuid.uuid4()), "kind": body.get("kind", "analysis"), "state": "running" if engine else "failed", "stage": "import_check" if engine else "configuration", "mode": "live" if engine else "unavailable", "progress": 0, "failures": [] if engine else ["Role 1/2 engine adapter is not integrated"], "result_ids": [], "scope": body, "timestamp": now()}
        app.state.repository.write(lambda data: data["runs"].update({run["id"]: copy.deepcopy(run)}))
        if engine:
            try:
                drafts = engine.analyze(body)
                for draft in drafts:
                    try:
                        result = app.state.service.create_requirement(draft, run["id"])
                        run["result_ids"].append(result["id"])
                    except (ValueError, DomainError) as exc:
                        run["failures"].append(str(exc))
                run.update(state="partial" if run["failures"] and run["result_ids"] else "failed" if run["failures"] else "succeeded", stage="completed", progress=1)
            except Exception as exc:
                run.update(state="failed", stage="failed", failures=[str(exc)])
            app.state.repository.write(lambda data: data["runs"].update({run["id"]: copy.deepcopy(run)}))
        return run

